import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as e,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"我如何使用现场 USB 设备恢复我的 Linux 系统 | LCTT x X-CMD","titleTemplate":false,"description":"我如何使用现场 USB 设备恢复我的 Linux 系统 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我如何使用现场 USB 设备恢复我的 Linux 系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我如何使用现场 USB 设备恢复我的 Linux 系统 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220912 How I recovered my Linux system using a Live USB device","title":"我如何使用现场 USB 设备恢复我的 Linux 系统","tag":"202209","desc":""},"relativePath":"202209/20220912 How I recovered my Linux system using a Live USB device.md","filePath":"[post].md"}'),c={name:"202209/20220912 How I recovered my Linux system using a Live USB device.md"};function h(u,s,g,b,m,k){const a=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="我如何使用现场-usb-设备恢复我的-linux-系统" tabindex="-1">我如何使用现场 USB 设备恢复我的 Linux 系统 <a class="header-anchor" href="#我如何使用现场-usb-设备恢复我的-linux-系统" aria-label="Permalink to “我如何使用现场 USB 设备恢复我的 Linux 系统”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/28/121226rh7vq7qhwhqzh76m.jpg" alt=""></p><blockquote><p>Fedora 现场 USB 发行版为引导和进入恢复模式提供了有效的解决方案。</p></blockquote><p>我的家庭实验室里有十几台物理计算机以及更多的虚拟机。这些系统中的大多数是我用来进行测试和实验的。我经常写使用自动化来简化系统管理任务的文章。我还在多个地方写过，我从自己的错误中学到的东西比几乎任何其他方式都多。</p><p>在过去的几周里，我学到了很多东西。</p><p>我给自己制造了一个大麻烦。作为多年的系统管理员，我写了数百篇关于 Linux 的文章和五本书，我应该对 Linux 更了解。话又说回来，我们都会犯错，这是一个重要的教训：你永远不会因为有经验而不犯错。</p><p>我不打算讨论我的错误的细节。告诉你这是一个错误就足够了，在我做之前我应该多考虑一下我在做什么。此外，细节并不是重点。经验不能让你免于犯下的每一个错误，但它可以帮助你恢复。这就是本文要讨论的内容：使用现场 USB 发行版启动并进入恢复模式。</p><h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to “问题”">​</a></h3><p>首先，我制造了问题，这本质上是 <code>/etc/default/grub</code> 文件的错误配置。接下来，我使用 Ansible 将错误配置的文件分发到我所有的物理计算机并运行 <code>grub2-mkconfig</code>。全部 12 个。这真的，真的很快。</p><p>除了两台之外，所有的都无法启动。它们在 Linux 启动的早期阶段崩溃，出现各种无法定位 <code>/root</code> 文件系统的错误。</p><p>我可以使用 root 密码进入“维护”模式，但是如果没有挂载 <code>/root</code>，即使是最简单的工具也无法访问。直接引导到恢复内核也不起作用。系统真的被破坏了。</p><h3 id="fedora-恢复模式" tabindex="-1">Fedora 恢复模式 <a class="header-anchor" href="#fedora-恢复模式" aria-label="Permalink to “Fedora 恢复模式”">​</a></h3><p>解决此问题的唯一方法是找到进入恢复模式的方法。当一切都失败时，Fedora 提供了一个非常酷的工具：用于安装 Fedora 新实例的<ruby>现场 USB<rt>Live USB</rt></ruby> 驱动器。</p><p>将 BIOS 设置为从现场 USB 设备启动后，我启动到 Fedora 36 Xfce 的<ruby>现场<rt>live</rt></ruby>用户桌面。我在桌面上打开了两个相邻的终端会话，并在两者中都切换到了 root 权限。</p><p>我在其中一个运行了 <code>lsblk</code> 以供参考。我使用该结果来识别 <code>/</code> 根分区以及 <code>boot</code> 和 <code>efi</code> 分区。我使用了我的一台虚拟机，如下所示。在这种情况下没有 <code>efi</code> 分区，因为此 VM 不使用 UEFI。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsblk</span></span>
<span class="line"><span>NAME          MAJ:MIN RM  SIZE RO TYPE MOUNTPOINTS</span></span>
<span class="line"><span>loop0           7:0    0  1.5G  1 loop</span></span>
<span class="line"><span>loop1           7:1    0    6G  1 loop</span></span>
<span class="line"><span>├─live-rw     253:0    0    6G  0 dm   /</span></span>
<span class="line"><span>└─live-base   253:1    0    6G  1 dm   </span></span>
<span class="line"><span>loop2           7:2    0   32G  0 loop</span></span>
<span class="line"><span>└─live-rw     253:0    0    6G  0 dm   /</span></span>
<span class="line"><span>sda             8:0    0  120G  0 disk</span></span>
<span class="line"><span>├─sda1          8:1    0    1G  0 part</span></span>
<span class="line"><span>└─sda2          8:2    0  119G  0 part</span></span>
<span class="line"><span>  ├─vg01-swap 253:2    0    4G  0 lvm  </span></span>
<span class="line"><span>  ├─vg01-tmp  253:3    0   10G  0 lvm  </span></span>
<span class="line"><span>  ├─vg01-var  253:4    0   20G  0 lvm  </span></span>
<span class="line"><span>  ├─vg01-home 253:5    0    5G  0 lvm  </span></span>
<span class="line"><span>  ├─vg01-usr  253:6    0   20G  0 lvm  </span></span>
<span class="line"><span>  └─vg01-root 253:7    0    5G  0 lvm  </span></span>
<span class="line"><span>sr0            11:0    1  1.6G  0 rom  /run/initramfs/live</span></span>
<span class="line"><span>zram0         252:0    0    8G  0 disk [SWAP]</span></span></code></pre></div><p><code>/dev/sda1</code> 分区很容易识别为 <code>/boot</code>，根（<code>/</code>）分区也很明显。</p><p>在另一个终端会话中，我执行了一系列步骤来恢复我的系统。特定的卷组名称和设备分区（例如 <code>/dev/sda1</code>）因系统而异。此处显示的命令特定于我的情况。</p><p>目标是使用现场 USB 引导并完成启动，然后仅在镜像目录中挂载必要的文件系统，并运行 <code>chroot</code> 命令在 chroot 镜像目录中运行 Linux。这种方法绕过损坏的 GRUB（或其他）配置文件。但是，它提供了一个完整的运行系统，其中安装了所有原始文件系统以进行恢复，既是所需工具的来源，也是要进行更改的目标。</p><p>以下是步骤和相关命令：</p><ol><li>创建目录 <code>/mnt/sysimage</code> 以提供 <code>chroot</code> 目录的位置。</li><li>将根分区挂载到 <code>/mnt/sysimage</code>：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount /dev/mapper/vg01-root /mnt/sysimage</span></span></code></pre></div></li><li>将 <code>/mnt/sysimage</code> 设为你的工作目录：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /mnt/sysimage</span></span></code></pre></div></li><li>挂载 <code>/boot</code> 和 <code>/boot/efi</code> 文件系统。</li><li>挂载其他主要文件系统。此步骤不需要像 <code>/home</code> 和 <code>/tmp</code> 这样的文件系统：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount /dev/mapper/vg01-usr usr</span></span>
<span class="line"><span></span></span>
<span class="line"><span># mount /dev/mapper/vg01-var var</span></span></code></pre></div></li><li>绑定已挂载的重要文件系统，它们必须在已经 chroot 的系统和原始的现场系统之间共享，而后者仍然在外部运行：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount --bind /sys sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span># mount --bind /proc proc</span></span></code></pre></div></li><li>一定要最后操作 <code>/dev</code> 目录，否则其他文件系统不能挂载：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount --bind /dev dev</span></span></code></pre></div></li><li>chroot 到系统镜像：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chroot /mnt/sysimage</span></span></code></pre></div></li></ol><p>系统现在已经准备好了，无论你需要做什么，都可以把它恢复到一个工作状态。然而，有一次我能够在这种状态下运行我的服务器数天，直到我能够研究测试出真正的修复方法。我并不推荐这样做，但在紧急情况下，当有任务需要启动和运行时，这可能是一个选择。</p><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to “解决方案”">​</a></h3><p>当我让每个系统进入恢复模式，修复就很容易了。因为我的系统现在就像成功启动一样工作，我只需对 <code>/etc/default/grub</code> 和 <code>/etc/fstab</code> 进行必要的更改并运行 <code>grub2-mkconfig &gt; boot/grub2/grub.cfg</code> 命令。我使用 <code>exit</code> 命令退出 chroot 环境，然后重启主机。</p><p>当然，我无法自动从我的意外事故中恢复过来。我必须在每台主机上手动执行整个过程，这是使用自动化快速和容易地传播我自己的错误的一点报应。</p><h3 id="得到教训" tabindex="-1">得到教训 <a class="header-anchor" href="#得到教训" aria-label="Permalink to “得到教训”">​</a></h3><p>尽管它们很有用，我曾经讨厌在我的一些系统管理员工作中举行的“经验教训”会议，但看来我确实需要提醒自己一些事情。因此，这里是我从这场自作自受的惨败中获得的“教训”。</p><p>首先，无法引导的十个系统使用了不同的卷组命名方案，而我的新 GRUB 配置没有考虑到这一点。我只是忽略了它们可能不同的事实。</p><ul><li>彻底考虑清楚。</li><li>并非所有系统都相同。</li><li>测试一切。</li><li>验证一切。</li><li>永远不要做假设。</li></ul><p>现在一切正常。希望我也聪明一点。</p><hr>`,31)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/22/9/recover-linux-system-live-usb"},{default:n(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/22/9/recover-linux-system-live-usb",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...s[2]||(s[2]=[e("David Both",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),i(a,{href:"https://github.com/lkxed"},{default:n(()=>[...s[3]||(s[3]=[e("lkxed",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const y=l(c,[["render",h]]);export{x as __pageData,y as default};
